#include <iostream>
struct Reading { int value; };
bool acceptable(const Reading& r){ return r.value>=0&&r.value<=100; }
int main(){ Reading a{42},b{101}; std::cout<<acceptable(a)<<' '<<acceptable(b)<<'\n'; }

#include <iostream>
class Counter {
 int value_=0;
public:
 bool add(int n){if(n<0||n>100-value_)return false;value_+=n;return true;}
 int value() const {return value_;}
};
int main(){Counter a,b; a.add(7); bool ok=a.add(94);std::cout<<a.value()<<' '<<b.value()<<' '<<ok<<'\n';}

